import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Realtime In-App Notifications — spec","description":"","frontmatter":{},"headers":[],"relativePath":"feature/realtime-notifications/spec.md","filePath":"feature/realtime-notifications/spec.md"}'),n={name:"feature/realtime-notifications/spec.md"};function s(r,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="realtime-in-app-notifications-—-spec" tabindex="-1">Realtime In-App Notifications — spec <a class="header-anchor" href="#realtime-in-app-notifications-—-spec" aria-label="Permalink to &quot;Realtime In-App Notifications — spec&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>New in-app notifications appear on the web within a second or two, with no page refresh, pushed over the existing STOMP WebSocket. Important actions that were silent before now create a notification for the people they affect.</p><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>As an Owner / Manager / Creator / Client, when something that needs my attention happens (my post fails to publish, my task is approved, a Client sends a request, my payment lands), I see a toast and the bell count update straight away, and a click takes me to the item.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ol><li>Every row inserted into <code>user_notifications</code> pushes a signal to the recipient&#39;s open web sessions (<code>/user/queue/notifications</code>) after the transaction commits. Rolled-back writes push nothing.</li><li>The signal carries no content. The web refetches <code>GET /api/v1/notifications/me</code> (the recipient&#39;s own inbox only), then shows a toast for each new unread item (at most 3) with a &quot;View&quot; action that opens <code>actionUrl</code>.</li><li>Items already unread when the page opens do not toast.</li><li>If the socket is down, the bell still refreshes on focus and every 120 s (was 30 s).</li><li>Admin web sessions are unchanged (the Admin bell has no user inbox).</li><li>New notification events (recipient → trigger):</li></ol><table tabindex="0"><thead><tr><th>Event</th><th>Recipient</th><th>Link</th></tr></thead><tbody><tr><td>Post published (first time)</td><td>Post author</td><td><code>/workspaces/{ws}/posts/{post}</code></td></tr><tr><td>Post failed (overall status FAILED) — <code>publishFailed</code> existed but was never called</td><td>Post author</td><td>same</td></tr><tr><td>Task approved at the last review step</td><td>Task assignee (not when they approved it themselves)</td><td><code>/workspaces/{ws}/tasks?task={id}</code></td></tr><tr><td>Admin moderation approve / block</td><td>Post author (in-app, next to the existing email)</td><td>post</td></tr><tr><td>SePay payment fulfilled (upgrade, renewal, credit top-up)</td><td>Agency Owner</td><td><code>/subscription</code></td></tr><tr><td>Invited to a Workspace (account already exists)</td><td>Invitee</td><td><code>/invitations/accept?token=…</code></td></tr><tr><td>Invitation accepted</td><td>Inviter</td><td><code>/workspaces/{ws}/members</code></td></tr><tr><td>Removed from a Workspace</td><td>Removed member</td><td><code>/workspaces</code></td></tr><tr><td>Workspace role changed</td><td>That member</td><td><code>/workspaces/{ws}</code></td></tr><tr><td>Client creates a Content Request</td><td>Workspace Managers</td><td><code>/workspaces/{ws}/requests</code></td></tr><tr><td>Content Request received / denied / accepted</td><td>Requesting Client</td><td>same</td></tr></tbody></table><p>Existing events (task assigned, comment/mention, review requested/rejected, section events, chat, package proposal, campaign review, mail batch finished, plan expired, Admin broadcast) now also arrive in realtime, with no change in their writers.</p><h2 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h2><ul><li>New key <code>notifications.open</code> (&quot;Xem&quot; / &quot;View&quot;) in <code>vi/notifications.json</code> and <code>en/notifications.json</code>.</li><li>Notification title/content are written in Vietnamese by the server, like every existing inbox row (unchanged convention).</li></ul><h2 id="light-dark-mode" tabindex="-1">Light/Dark mode <a class="header-anchor" href="#light-dark-mode" aria-label="Permalink to &quot;Light/Dark mode&quot;">​</a></h2><p>Toasts use the existing <code>sonner</code> theme; no new colours.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><ul><li>A failed inbox write never fails the business action it reports on: billing and moderation write inside the action&#39;s own transaction; publish callback and content requests catch and log.</li><li>Listener connection loss: logs a warning, reconnects every 5 s. Polling covers the gap.</li></ul><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><ul><li>Duplicate publish callbacks / retried webhooks: deterministic ids (<code>on conflict do nothing</code>).</li><li>Admin broadcast to thousands of users: Postgres folds identical NOTIFY payloads per transaction, so one signal per recipient.</li><li>Several business-service instances: each LISTENs and reaches only its own sessions.</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p>Migration applied, backend tests green, web <code>tsc</code> + eslint clean, live STOMP probe receives the signal for an inserted row.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><p>Mobile push (FCM), per-category notification preferences, cross-tab read sync.</p>',21)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
